(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.KanjiAbilityGuide=api;})(typeof window!=='undefined'?window:globalThis,function(){
'use strict';
const conditions={sturdy:'相手に押されて場外へ出るとき',guard:'相手の攻撃を受けたとき',strike:'強さ60%以上の自分の発射で相手に当たったとき',anchor:'相手から衝突を受ける直前',counter:'正面から相手の攻撃を受けたとき',dodge:'相手の攻撃を受け、安全な回避先があるとき',chase:'自分の発射で相手を押し、相手が近くに残ったとき',magnet:'自分の発射で別の自分のコマに当てたとき',glide:'相手に吹き飛ばされて0.3秒後',brake:'自分の発射から0.9秒後',return:'自分の発射で場外へ出るとき',backwater:'中心から盤面半径の72%以上離れている間',resonance:'約3コマ分以内に同じ属性の自分がいる間',charge:'自分の発射を見送ったとき',一:'発射中に相手のすぐ横をすれ違ったとき',小:'自分の発射後',口:'常時・相手の攻撃を受けたとき',山:'発射後、最初に相手へ当たったとき',大:'発射後、最初に衝突したとき',十:'最初の衝突後、上下左右に別の相手がいるとき',凹:'両方のターンで、くぼみの内側に相手が接触したとき',弾:'発射後、最初に衝突したとき',風:'発射中の別の自分が近くを通過したとき',粘:'相手から衝突を受けたとき',回:'発射後の回転中に相手へ衝突したとき',矢:'自分の発射・相手への衝突時',盾:'平たい正面で攻撃を受けるとき・場外へ出るとき',合:'近くの別の自分が発射したとき',独:'近くに別の自分がいない間',助け合い:'自分のコマが近くの木の範囲内で攻撃を受けるとき',猛進:'自分の発射で最初に相手へぶつかったとき',大地の守り:'相手の攻撃を受けるとき',貫通:'自分の発射で相手へぶつかったとき',流れ戻り:'自分の番の開始時、中心から盤面半径の65%以上離れているとき'};
function fields(a,kind='ruby'){const description=a?.description||'効果なし',limit=description.match(/1対局\d+回|各ターン1回|1発射1(?:回|体まで)|1回の発射につき1回|発射のたびに1回/);return [['発動条件',conditions[a?.id]||conditions[a?.char]||conditions[a?.name?.split('：').at(-1)]||'説明に記載された条件'],['効果',description],['回数',a?.char==='盾'?'正面防御は回数制限なし／落下防止は1対局1回':limit?limit[0]:'条件を満たすたび・満たしている間'],['重複',kind==='ruby'?`同じ効果は最大3個分。現在${a?.stacks||1}個分の効果を表示。`:kind==='element'?'生存している自分の同属性コマ数で変化（最大3体）。木は範囲条件も必要。':'特性は各コマに適用。追い風は複数あっても重複せず、峰打ちの弱体化も重複しません。']];}
function text(a,kind){return fields(a,kind).map(([label,value])=>label+'：'+value).join('\n');}
function append(box,a,kind,doc=document){const dl=doc.createElement('dl');dl.className='ability-guide';for(const [label,value]of fields(a,kind)){const row=doc.createElement('div'),dt=doc.createElement('dt'),dd=doc.createElement('dd');dt.textContent=label;dd.textContent=value;row.append(dt,dd);dl.append(row);}box.append(dl);return dl;}
function ratio(item,p,state={},bases=[]){if(/^completedJis[1-4]$/.test(item.key)){const jis=Number(item.key.slice(-1)),all=bases.filter(i=>i.jis===jis),found=new Set([...(state.characterDiscoveries||[]),...(state.inventory||[]).map(i=>i.char)]);return all.length?all.filter(i=>found.has(i.char)).length/all.length:0;}return Math.min(...Object.entries({[item.key]:item.value,...item.requires}).map(([key,target])=>{const floor=/^highest(?:Balanced|Free|Online)RP$/.test(key)?1200:0;return Math.max(0,Math.min(1,((p[key]||0)-floor)/Math.max(1,target-floor)));}));}
function matches(filter,unlocked,item,p,state,bases){return filter==='unlocked'?unlocked:filter==='locked'?!unlocked:filter==='near'?!unlocked&&ratio(item,p,state,bases)>=.8:true;}
return{fields,text,append,ratio,matches};});
